		/** 
		 * Tests creating a new Review.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Review");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Review" );

			try {            
				Review entity = ReviewService.getReviewInstance().createReview( generateNewEntity() );
				thePrimaryKey = entity.getReviewId();
				LOGGER.info( "-- Successfully created a Review with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Review. 
		 */
		public Review testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Review" );

			Review entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Review with primary key" );
			msg.append( thePrimaryKey );
			
			ReviewFetchOneSummary fetchOneSummary = new ReviewFetchOneSummary( thePrimaryKey );

			try {
				entity = ReviewService.getReviewInstance().getReview( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Review " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Review.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Review." );

			StringBuilder msg = new StringBuilder( "Failed to update a Review : " );        
			Review entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Review." );

				// for use later on...
				thePrimaryKey = entity.getReviewId();

				ReviewService proxy = ReviewService.getReviewInstance();            
				proxy.updateReview( entity );   

				LOGGER.info( "-- Successfully saved Review - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Review.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Review." );

			try{
			    Review entity = testRead(); 
				ReviewService.getReviewInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Review with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Review with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Reviews.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Reviews:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Review : " );        
			List<Review> collection  = null;

			try {
				// call the static get method on the ReviewService
				collection = ReviewService.getReviewInstance().getAllReview();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Review entity = null;            
					Iterator<Review> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getReviewId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/**
		 * Assigns a common log handler for each test class in the suite
		 * @param		handler	Handler
		 * @return		ReviewTest
		 */
		public ReviewTest setHandler(Handler handler) {
			this.handler = handler;
			LOGGER.addHandler(handler); // assign so the LOGGER can only output results to the Handler
			return this;
		}

		/**
		 * Returns a new populated Review
		 * 
		 * @return Review
		 */
		protected Review generateNewEntity() {
			Review entity = new Review( null,  0,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),   new Date(),  null,  null,  null,  ReviewStatus.values()[0] );
			
			return( entity );
		}

